insert into public.districts (id, slug, name, side, avg_rent_usd, lat, lng, description, highlights, cover_url) values ('dist-besiktas', 'besiktas', '{"fa":"بشیکتاش","en":"Beşiktaş"}'::jsonb, 'european', 450, 41.043, 29.007, '{"fa":"قلب دانشجویی استانبول: کنار بسفر، پر از کافه، کتابفروشی و زندگی شبانه. میزبان بغازیچی، ییلدیز تکنیک، باهچه‌شهیر و گالاتاسرای. اجاره بالاست اما همه‌چیز پیاده در دسترس است.","en":"Istanbul''s student heart on the Bosphorus: cafés, bookshops and nightlife. Home to Boğaziçi, Yıldız Technical, Bahçeşehir and Galatasaray. Rent is high but everything is walkable."}'::jsonb, '[{"fa":"دسترسی عالی به مترو و اتوبوس دریایی","en":"Metro + ferry access"},{"fa":"امن و پر از دانشجو","en":"Safe and student-dense"},{"fa":"گران‌ترین اجاره‌ها در سمت اروپایی","en":"Among the priciest rents on the European side"}]'::jsonb, null) on conflict (id) do update set slug = excluded.slug, name = excluded.name, side = excluded.side, avg_rent_usd = excluded.avg_rent_usd, lat = excluded.lat, lng = excluded.lng, description = excluded.description, highlights = excluded.highlights, cover_url = excluded.cover_url;
insert into public.districts (id, slug, name, side, avg_rent_usd, lat, lng, description, highlights, cover_url) values ('dist-sariyer', 'sariyer', '{"fa":"ساری‌یر","en":"Sarıyer"}'::jsonb, 'european', 420, 41.108, 29.02, '{"fa":"شمال سمت اروپایی؛ منطقه مسلک (Maslak) با برج‌های اداری و دانشگاه‌های ITÜ، کوچ، استینیه، بیکنت و نیشان‌تاشی. سبز، آرام و نزدیک جنگل بلگراد.","en":"Northern European side; the Maslak business district hosts ITU, Koç, İstinye, Beykent and Nişantaşı universities. Green, calm, next to Belgrad Forest."}'::jsonb, '[{"fa":"خوابگاه‌های زیاد اطراف مسلک","en":"Many dorms around Maslak"},{"fa":"مترو M2 مستقیم به تاکسیم","en":"M2 metro straight to Taksim"}]'::jsonb, null) on conflict (id) do update set slug = excluded.slug, name = excluded.name, side = excluded.side, avg_rent_usd = excluded.avg_rent_usd, lat = excluded.lat, lng = excluded.lng, description = excluded.description, highlights = excluded.highlights, cover_url = excluded.cover_url;
insert into public.districts (id, slug, name, side, avg_rent_usd, lat, lng, description, highlights, cover_url) values ('dist-sisli', 'sisli', '{"fa":"شیشلی","en":"Şişli"}'::jsonb, 'european', 480, 41.06, 28.987, '{"fa":"مرکز تجاری و خرید: نیشان‌تاشی، محیدیه‌کوی، مجیدیه‌کوی. پر از فارسی‌زبان، رستوران ایرانی و دفاتر خدماتی. دانشگاه‌های بیلیم و نزدیک به بسیاری از پردیس‌ها.","en":"Commercial and shopping core: Nişantaşı, Mecidiyeköy. Large Persian-speaking community, Iranian restaurants and services. Central to most campuses."}'::jsonb, '[{"fa":"بزرگ‌ترین جامعه ایرانی استانبول","en":"Largest Iranian community"},{"fa":"همه خطوط مترو از اینجا رد می‌شوند","en":"Metro hub"}]'::jsonb, null) on conflict (id) do update set slug = excluded.slug, name = excluded.name, side = excluded.side, avg_rent_usd = excluded.avg_rent_usd, lat = excluded.lat, lng = excluded.lng, description = excluded.description, highlights = excluded.highlights, cover_url = excluded.cover_url;
insert into public.districts (id, slug, name, side, avg_rent_usd, lat, lng, description, highlights, cover_url) values ('dist-fatih', 'fatih', '{"fa":"فاتح","en":"Fatih"}'::jsonb, 'european', 320, 41.017, 28.95, '{"fa":"شبه‌جزیره تاریخی: دانشگاه استانبول، کادیر هاس، بزم‌عالم، فاتح سلطان محمد. ارزان‌تر، سنتی‌تر و پر از تاریخ. به لاله‌لی و آکسارای نزدیک است.","en":"The historic peninsula: Istanbul University, Kadir Has, Bezmialem, Fatih Sultan Mehmet. Cheaper, traditional and full of history. Near Laleli and Aksaray."}'::jsonb, '[{"fa":"اجاره مناسب نزدیک دانشگاه استانبول","en":"Affordable near Istanbul University"},{"fa":"تراموا T1 و مترو M2","en":"T1 tram + M2 metro"}]'::jsonb, null) on conflict (id) do update set slug = excluded.slug, name = excluded.name, side = excluded.side, avg_rent_usd = excluded.avg_rent_usd, lat = excluded.lat, lng = excluded.lng, description = excluded.description, highlights = excluded.highlights, cover_url = excluded.cover_url;
insert into public.districts (id, slug, name, side, avg_rent_usd, lat, lng, description, highlights, cover_url) values ('dist-beyoglu', 'beyoglu', '{"fa":"بی‌اوغلو","en":"Beyoğlu"}'::jsonb, 'european', 430, 41.03, 28.975, '{"fa":"تاکسیم، جیهانگیر، کاراکوی: زندگی شهری، هنر و رویدادها. گالاتا و دانشگاه‌های هنری نزدیک. برای کسانی که زندگی پرجنب‌وجوش می‌خواهند.","en":"Taksim, Cihangir, Karaköy: urban life, arts and events. Galata University and art schools nearby. For students who want the buzz."}'::jsonb, '[{"fa":"فرهنگ و هنر","en":"Culture & arts"},{"fa":"شلوغ؛ برای تمرکز بهتر نیست","en":"Busy; not ideal for quiet study"}]'::jsonb, null) on conflict (id) do update set slug = excluded.slug, name = excluded.name, side = excluded.side, avg_rent_usd = excluded.avg_rent_usd, lat = excluded.lat, lng = excluded.lng, description = excluded.description, highlights = excluded.highlights, cover_url = excluded.cover_url;
insert into public.districts (id, slug, name, side, avg_rent_usd, lat, lng, description, highlights, cover_url) values ('dist-kadikoy', 'kadikoy', '{"fa":"کادیکوی","en":"Kadıköy"}'::jsonb, 'asian', 400, 40.99, 29.03, '{"fa":"محبوب‌ترین منطقه سمت آسیایی برای جوانان: موضا، باغداد جادسی، بازار ماهی، کافه و کنسرت. دانشگاه مرمرا و مدنیت در گوزتپه. با کشتی ۲۰ دقیقه تا سمت اروپایی.","en":"The Asian side''s favourite for young people: Moda, Bağdat Avenue, food markets, cafés and gigs. Marmara and Medeniyet universities in Göztepe. Twenty minutes by ferry to Europe."}'::jsonb, '[{"fa":"امن، مدرن و ارزان‌تر از بشیکتاش","en":"Safe, modern, cheaper than Beşiktaş"},{"fa":"مترو M4 و مارمارای","en":"M4 metro + Marmaray"}]'::jsonb, null) on conflict (id) do update set slug = excluded.slug, name = excluded.name, side = excluded.side, avg_rent_usd = excluded.avg_rent_usd, lat = excluded.lat, lng = excluded.lng, description = excluded.description, highlights = excluded.highlights, cover_url = excluded.cover_url;
insert into public.districts (id, slug, name, side, avg_rent_usd, lat, lng, description, highlights, cover_url) values ('dist-uskudar', 'uskudar', '{"fa":"اسکودار","en":"Üsküdar"}'::jsonb, 'asian', 330, 41.025, 29.03, '{"fa":"ساحل آسیایی روبه‌روی بسفر، سنتی‌تر و آرام‌تر. دانشگاه اسکودار، ۲۹ مایس و نزدیک مدیپول. اجاره منطقی و دسترسی عالی با مارمارای.","en":"Asian shore facing the Bosphorus, more traditional and calm. Üsküdar University, 29 Mayıs and close to Medipol. Reasonable rent, excellent Marmaray access."}'::jsonb, '[{"fa":"مارمارای: ۴ دقیقه تا سمت اروپایی","en":"Marmaray: 4 min to Europe"},{"fa":"محله‌های خانوادگی","en":"Family neighbourhoods"}]'::jsonb, null) on conflict (id) do update set slug = excluded.slug, name = excluded.name, side = excluded.side, avg_rent_usd = excluded.avg_rent_usd, lat = excluded.lat, lng = excluded.lng, description = excluded.description, highlights = excluded.highlights, cover_url = excluded.cover_url;
insert into public.districts (id, slug, name, side, avg_rent_usd, lat, lng, description, highlights, cover_url) values ('dist-atasehir', 'atasehir', '{"fa":"آتاشهیر","en":"Ataşehir"}'::jsonb, 'asian', 380, 40.98, 29.12, '{"fa":"مرکز مالی جدید استانبول. یدی‌تپه، آجی‌بادم و فنرباغچه اینجا هستند. مدرن، برج‌نشین و مناسب دانشجویان پزشکی.","en":"Istanbul''s new financial centre. Home to Yeditepe, Acıbadem and Fenerbahçe universities. Modern, high-rise, popular with medical students."}'::jsonb, '[{"fa":"نزدیک بیمارستان‌های آموزشی","en":"Near teaching hospitals"}]'::jsonb, null) on conflict (id) do update set slug = excluded.slug, name = excluded.name, side = excluded.side, avg_rent_usd = excluded.avg_rent_usd, lat = excluded.lat, lng = excluded.lng, description = excluded.description, highlights = excluded.highlights, cover_url = excluded.cover_url;
insert into public.districts (id, slug, name, side, avg_rent_usd, lat, lng, description, highlights, cover_url) values ('dist-maltepe', 'maltepe', '{"fa":"مال‌تپه","en":"Maltepe"}'::jsonb, 'asian', 300, 40.93, 29.15, '{"fa":"ساحلی و آرام در سمت آسیایی با دانشگاه مال‌تپه. اجاره پایین و پارک ساحلی بزرگ.","en":"Coastal and calm on the Asian side with Maltepe University. Low rent and a huge seaside park."}'::jsonb, array[]::text[], null) on conflict (id) do update set slug = excluded.slug, name = excluded.name, side = excluded.side, avg_rent_usd = excluded.avg_rent_usd, lat = excluded.lat, lng = excluded.lng, description = excluded.description, highlights = excluded.highlights, cover_url = excluded.cover_url;
insert into public.districts (id, slug, name, side, avg_rent_usd, lat, lng, description, highlights, cover_url) values ('dist-tuzla', 'tuzla', '{"fa":"توزلا","en":"Tuzla"}'::jsonb, 'asian', 260, 40.86, 29.33, '{"fa":"انتهای شرقی استانبول: سابانجی، اوکان و پیری رئیس با پردیس‌های بزرگ و خوابگاه‌های داخل دانشگاه. از مرکز شهر دور است (۶۰–۹۰ دقیقه) اما زندگی پردیسی کامل دارد.","en":"Istanbul''s eastern edge: Sabancı, Okan and Piri Reis with large campuses and on-site dorms. Far from the centre (60–90 min) but a full campus lifestyle."}'::jsonb, '[{"fa":"خوابگاه داخل پردیس","en":"On-campus dorms"},{"fa":"دور از مرکز","en":"Far from the centre"}]'::jsonb, null) on conflict (id) do update set slug = excluded.slug, name = excluded.name, side = excluded.side, avg_rent_usd = excluded.avg_rent_usd, lat = excluded.lat, lng = excluded.lng, description = excluded.description, highlights = excluded.highlights, cover_url = excluded.cover_url;
insert into public.districts (id, slug, name, side, avg_rent_usd, lat, lng, description, highlights, cover_url) values ('dist-bakirkoy', 'bakirkoy', '{"fa":"باکرکوی","en":"Bakırköy"}'::jsonb, 'european', 350, 40.98, 28.87, '{"fa":"ساحل مرمره در سمت اروپایی، نزدیک فرودگاه قدیم و دانشگاه کولتور. مرفه، ساحلی و با دسترسی مارمارای.","en":"Marmara coast on the European side, near Kültür University. Well-off, seaside, Marmaray access."}'::jsonb, array[]::text[], null) on conflict (id) do update set slug = excluded.slug, name = excluded.name, side = excluded.side, avg_rent_usd = excluded.avg_rent_usd, lat = excluded.lat, lng = excluded.lng, description = excluded.description, highlights = excluded.highlights, cover_url = excluded.cover_url;
insert into public.districts (id, slug, name, side, avg_rent_usd, lat, lng, description, highlights, cover_url) values ('dist-avcilar', 'avcilar', '{"fa":"آوجیلار","en":"Avcılar"}'::jsonb, 'european', 230, 40.98, 28.72, '{"fa":"غرب استانبول؛ پردیس دانشگاه استانبول-جراح‌پاشا و گلیشیم. یکی از ارزان‌ترین مناطق برای دانشجو با مترو‌بوس.","en":"West Istanbul; Istanbul University-Cerrahpaşa campus and Gelişim University. One of the cheapest student areas, on the Metrobüs line."}'::jsonb, '[{"fa":"ارزان‌ترین اجاره‌ها","en":"Cheapest rents"}]'::jsonb, null) on conflict (id) do update set slug = excluded.slug, name = excluded.name, side = excluded.side, avg_rent_usd = excluded.avg_rent_usd, lat = excluded.lat, lng = excluded.lng, description = excluded.description, highlights = excluded.highlights, cover_url = excluded.cover_url;
insert into public.districts (id, slug, name, side, avg_rent_usd, lat, lng, description, highlights, cover_url) values ('dist-beykoz', 'beykoz', '{"fa":"بیکوز","en":"Beykoz"}'::jsonb, 'asian', 330, 41.1, 29.1, '{"fa":"سبزترین منطقه بسفر در سمت آسیایی: مدیپول (کاواجیک)، دانشگاه ترک-آلمان و بیکوز. آرام و طبیعت‌محور.","en":"Greenest Bosphorus district on the Asian side: Medipol (Kavacık), Turkish-German University and Beykoz. Quiet and nature-focused."}'::jsonb, array[]::text[], null) on conflict (id) do update set slug = excluded.slug, name = excluded.name, side = excluded.side, avg_rent_usd = excluded.avg_rent_usd, lat = excluded.lat, lng = excluded.lng, description = excluded.description, highlights = excluded.highlights, cover_url = excluded.cover_url;
insert into public.districts (id, slug, name, side, avg_rent_usd, lat, lng, description, highlights, cover_url) values ('dist-eyupsultan', 'eyupsultan', '{"fa":"ایوب‌سلطان","en":"Eyüpsultan"}'::jsonb, 'european', 300, 41.05, 28.94, '{"fa":"کنار شاخ طلایی؛ بیلگی (سانترال‌استانبول) و حالیچ. تاریخی، مذهبی و ارزان‌تر از مرکز.","en":"On the Golden Horn; Bilgi (santralistanbul) and Haliç universities. Historic, devout, cheaper than the centre."}'::jsonb, array[]::text[], null) on conflict (id) do update set slug = excluded.slug, name = excluded.name, side = excluded.side, avg_rent_usd = excluded.avg_rent_usd, lat = excluded.lat, lng = excluded.lng, description = excluded.description, highlights = excluded.highlights, cover_url = excluded.cover_url;
insert into public.districts (id, slug, name, side, avg_rent_usd, lat, lng, description, highlights, cover_url) values ('dist-bagcilar', 'bagcilar', '{"fa":"باغجیلار","en":"Bağcılar"}'::jsonb, 'european', 240, 41.04, 28.85, '{"fa":"پرجمعیت و مقرون‌به‌صرفه؛ پردیس آلتین‌باش. دسترسی مترو M1 و M3.","en":"Dense and affordable; Altınbaş campus. M1 and M3 metro."}'::jsonb, array[]::text[], null) on conflict (id) do update set slug = excluded.slug, name = excluded.name, side = excluded.side, avg_rent_usd = excluded.avg_rent_usd, lat = excluded.lat, lng = excluded.lng, description = excluded.description, highlights = excluded.highlights, cover_url = excluded.cover_url;
insert into public.districts (id, slug, name, side, avg_rent_usd, lat, lng, description, highlights, cover_url) values ('dist-zeytinburnu', 'zeytinburnu', '{"fa":"زیتین‌بورنو","en":"Zeytinburnu"}'::jsonb, 'european', 290, 41, 28.9, '{"fa":"نزدیک توپکاپی و مرکز؛ بیرونی، توپکاپی و ینی‌یوزییل. جامعه فارسی‌زبان بزرگ و حمل‌ونقل عالی.","en":"Near Topkapı and the centre; Biruni, Topkapı and Yeni Yüzyıl universities. Large Persian-speaking community and great transport."}'::jsonb, '[{"fa":"محله ایرانی‌ها","en":"Iranian neighbourhood"}]'::jsonb, null) on conflict (id) do update set slug = excluded.slug, name = excluded.name, side = excluded.side, avg_rent_usd = excluded.avg_rent_usd, lat = excluded.lat, lng = excluded.lng, description = excluded.description, highlights = excluded.highlights, cover_url = excluded.cover_url;
insert into public.districts (id, slug, name, side, avg_rent_usd, lat, lng, description, highlights, cover_url) values ('dist-kucukcekmece', 'kucukcekmece', '{"fa":"کوچوک‌چکمجه","en":"Küçükçekmece"}'::jsonb, 'european', 250, 41.02, 28.78, '{"fa":"پردیس اصلی دانشگاه آیدین و صباح‌الدین زعیم؛ منطقه‌ای ارزان با مترو M1.","en":"Main campus of Aydın University and Sabahattin Zaim; affordable, on the M1 line."}'::jsonb, array[]::text[], null) on conflict (id) do update set slug = excluded.slug, name = excluded.name, side = excluded.side, avg_rent_usd = excluded.avg_rent_usd, lat = excluded.lat, lng = excluded.lng, description = excluded.description, highlights = excluded.highlights, cover_url = excluded.cover_url;
insert into public.districts (id, slug, name, side, avg_rent_usd, lat, lng, description, highlights, cover_url) values ('dist-basaksehir', 'basaksehir', '{"fa":"باشاک‌شهیر","en":"Başakşehir"}'::jsonb, 'european', 280, 41.09, 28.8, '{"fa":"شهر نوساز و برنامه‌ریزی‌شده؛ ابن‌خلدون و بیمارستان شهر. خانوادگی و تمیز.","en":"New planned city; Ibn Haldun University and the City Hospital. Family-friendly and tidy."}'::jsonb, array[]::text[], null) on conflict (id) do update set slug = excluded.slug, name = excluded.name, side = excluded.side, avg_rent_usd = excluded.avg_rent_usd, lat = excluded.lat, lng = excluded.lng, description = excluded.description, highlights = excluded.highlights, cover_url = excluded.cover_url;
