insert into public.universities (id, city, currency, status, logo_url, cover_url, slug, short_name, name, type, district_id, founded, website, description, languages, avg_tuition_min, avg_tuition_max, student_count, intl_student_pct, has_dorm, lat, lng, editorial_score, is_featured, highlights, eduways_discount_pct) values ('uni-istanbul-technical-university', 'istanbul', 'USD', 'published', null, null, 'istanbul-technical-university', 'İTÜ', '{"fa":"دانشگاه فنی استانبول (İTÜ)","en":"Istanbul Technical University (ITU)"}'::jsonb, 'public', 'dist-sariyer', 1773, 'https://www.itu.edu.tr', '{"fa":"قدیمی‌ترین دانشگاه فنی جهان پس از پاریس و پراگ و معتبرترین دانشگاه مهندسی ترکیه. پردیس اصلی در آیازاغا/مسلک با بیش از ۳۰ هزار دانشجو. پذیرش بین‌المللی رقابتی است (YÖS/SAT با نمره بالا) اما شهریه دولتی بسیار پایین است و مدرک آن در جهان شناخته‌شده است.","en":"One of the world’s oldest technical universities and Türkiye’s most prestigious engineering school. Main campus in Ayazağa/Maslak with 30,000+ students. International admission is competitive (high YÖS/SAT) but public tuition is very low and the degree is globally recognised."}'::jsonb, array['tr','en']::text[], 1500, 4500, 36000, 6, true, 41.1055, 29.0236, 92, true, '[{"fa":"رتبه ۱ مهندسی ترکیه در اکثر رتبه‌بندی‌ها","en":"#1 engineering school in Türkiye in most rankings"},{"fa":"۳۰٪ از برنامه‌ها ۱۰۰٪ انگلیسی","en":"Around 30% of programs fully in English"},{"fa":"پردیس مسلک با مترو M2","en":"Maslak campus on the M2 metro"}]'::jsonb, null) on conflict (id) do update set city = excluded.city, currency = excluded.currency, status = excluded.status, logo_url = excluded.logo_url, cover_url = excluded.cover_url, slug = excluded.slug, short_name = excluded.short_name, name = excluded.name, type = excluded.type, district_id = excluded.district_id, founded = excluded.founded, website = excluded.website, description = excluded.description, languages = excluded.languages, avg_tuition_min = excluded.avg_tuition_min, avg_tuition_max = excluded.avg_tuition_max, student_count = excluded.student_count, intl_student_pct = excluded.intl_student_pct, has_dorm = excluded.has_dorm, lat = excluded.lat, lng = excluded.lng, editorial_score = excluded.editorial_score, is_featured = excluded.is_featured, highlights = excluded.highlights, eduways_discount_pct = excluded.eduways_discount_pct;
insert into public.universities (id, city, currency, status, logo_url, cover_url, slug, short_name, name, type, district_id, founded, website, description, languages, avg_tuition_min, avg_tuition_max, student_count, intl_student_pct, has_dorm, lat, lng, editorial_score, is_featured, highlights, eduways_discount_pct) values ('uni-bogazici-university', 'istanbul', 'USD', 'published', null, null, 'bogazici-university', 'Boğaziçi', '{"fa":"دانشگاه بغازیچی","en":"Boğaziçi University"}'::jsonb, 'public', 'dist-besiktas', 1863, 'https://bogazici.edu.tr', '{"fa":"بنیان‌گذاری‌شده به‌عنوان رابرت کالج؛ زبان تدریس کاملاً انگلیسی، بالاترین ورودی‌های کنکور ترکیه و پردیسی خیره‌کننده روی بسفر. برای دانشجویان بین‌المللی سخت‌ترین پذیرش در میان دولتی‌ها، اما کم‌هزینه‌ترین مدرک انگلیسی ممتاز.","en":"Founded as Robert College; fully English-medium, the top YKS intake in Türkiye and a stunning Bosphorus campus. The hardest public admission for internationals, yet the cheapest elite English degree in the country."}'::jsonb, array['en']::text[], 1800, 5000, 17000, 5, true, 41.0853, 29.0512, 94, true, '[{"fa":"۱۰۰٪ انگلیسی","en":"100% English-medium"},{"fa":"رتبه ۱–۲ ترکیه در QS و THE","en":"Top-2 in Türkiye in QS and THE"}]'::jsonb, null) on conflict (id) do update set city = excluded.city, currency = excluded.currency, status = excluded.status, logo_url = excluded.logo_url, cover_url = excluded.cover_url, slug = excluded.slug, short_name = excluded.short_name, name = excluded.name, type = excluded.type, district_id = excluded.district_id, founded = excluded.founded, website = excluded.website, description = excluded.description, languages = excluded.languages, avg_tuition_min = excluded.avg_tuition_min, avg_tuition_max = excluded.avg_tuition_max, student_count = excluded.student_count, intl_student_pct = excluded.intl_student_pct, has_dorm = excluded.has_dorm, lat = excluded.lat, lng = excluded.lng, editorial_score = excluded.editorial_score, is_featured = excluded.is_featured, highlights = excluded.highlights, eduways_discount_pct = excluded.eduways_discount_pct;
insert into public.universities (id, city, currency, status, logo_url, cover_url, slug, short_name, name, type, district_id, founded, website, description, languages, avg_tuition_min, avg_tuition_max, student_count, intl_student_pct, has_dorm, lat, lng, editorial_score, is_featured, highlights, eduways_discount_pct) values ('uni-istanbul-university', 'istanbul', 'USD', 'published', null, null, 'istanbul-university', 'İÜ', '{"fa":"دانشگاه استانبول","en":"Istanbul University"}'::jsonb, 'public', 'dist-fatih', 1453, 'https://www.istanbul.edu.tr', '{"fa":"قدیمی‌ترین و بزرگ‌ترین دانشگاه ترکیه در قلب شبه‌جزیره تاریخی (بیازیت). طیف وسیعی از رشته‌ها از پزشکی (چاپا) و حقوق تا ادبیات و مدیریت. شهریه دولتی و پذیرش با آزمون İÜYÖS.","en":"Türkiye’s oldest and largest university in the historic peninsula (Beyazıt). A vast range of programs from medicine (Çapa) and law to literature and business. Public tuition and admission via its own İÜYÖS exam."}'::jsonb, array['tr','en']::text[], 1000, 9000, 70000, 8, true, 41.013, 28.9635, 88, true, '[{"fa":"دانشکده پزشکی استانبول (چاپا) — معتبرترین در ترکیه","en":"Istanbul Faculty of Medicine (Çapa) — the most prestigious in Türkiye"},{"fa":"آزمون اختصاصی İÜYÖS که ایرانی‌ها در آن موفق‌اند","en":"Own İÜYÖS exam, very familiar to Iranian students"}]'::jsonb, null) on conflict (id) do update set city = excluded.city, currency = excluded.currency, status = excluded.status, logo_url = excluded.logo_url, cover_url = excluded.cover_url, slug = excluded.slug, short_name = excluded.short_name, name = excluded.name, type = excluded.type, district_id = excluded.district_id, founded = excluded.founded, website = excluded.website, description = excluded.description, languages = excluded.languages, avg_tuition_min = excluded.avg_tuition_min, avg_tuition_max = excluded.avg_tuition_max, student_count = excluded.student_count, intl_student_pct = excluded.intl_student_pct, has_dorm = excluded.has_dorm, lat = excluded.lat, lng = excluded.lng, editorial_score 