insert into public.universities (id, city, currency, status, logo_url, cover_url, slug, short_name, name, type, district_id, founded, website, description, languages, avg_tuition_min, avg_tuition_max, student_count, intl_student_pct, has_dorm, lat, lng, editorial_score, is_featured, highlights, eduways_discount_pct) values ('uni-istanbul-university-cerrahpasa', 'istanbul', 'USD', 'published', null, null, 'istanbul-university-cerrahpasa', 'İÜC', '{"fa":"دانشگاه استانبول-جراح‌پاشا","en":"Istanbul University-Cerrahpaşa"}'::jsonb, 'public', 'dist-avcilar', 2018, 'https://www.iuc.edu.tr', '{"fa":"در ۲۰۱۸ از دانشگاه استانبول جدا شد؛ میزبان دانشکده پزشکی جراح‌پاشا، مهندسی (آوجیلار)، دامپزشکی، جنگلداری و پرستاری فلورانس نایتینگل.","en":"Split from Istanbul University in 2018; hosts the Cerrahpaşa Faculty of Medicine, engineering (Avcılar), veterinary, forestry and the Florence Nightingale nursing faculty."}'::jsonb, array['tr','en']::text[], 1000, 9000, 40000, 7, true, 40.99, 28.722, 84, false, null, null) on conflict (id) do update set city = excluded.city, currency = excluded.currency, status = excluded.status, logo_url = excluded.logo_url, cover_url = excluded.cover_url, slug = excluded.slug, short_name = excluded.short_name, name = excluded.name, type = excluded.type, district_id = excluded.district_id, founded = excluded.founded, website = excluded.website, description = excluded.description, languages = excluded.languages, avg_tuition_min = excluded.avg_tuition_min, avg_tuition_max = excluded.avg_tuition_max, student_count = excluded.student_count, intl_student_pct = excluded.intl_student_pct, has_dorm = excluded.has_dorm, lat = excluded.lat, lng = excluded.lng, editorial_score = excluded.editorial_score, is_featured = excluded.is_featured, highlights = excluded.highlights, eduways_discount_pct = excluded.eduways_discount_pct;
