insert into public.admission_requirements (id, university_id, level, documents, exams, deadlines, notes) values ('req-istanbul-technical-university-bachelor', 'uni-istanbul-technical-university', 'bachelor', '[{"name":{"fa":"دیپلم دبیرستان (یا پیش‌دانشگاهی)","en":"High-school diploma"},"required":true,"note":{"fa":"ترجمه رسمی ترکی یا انگلیسی + تأیید نوتر/کنسولگری","en":"Official Turkish/English translation + notary/consulate attestation"}},{"name":{"fa":"ریزنمرات سه سال آخر دبیرستان","en":"High-school transcript (last 3 years)"},"required":true,"note":{"fa":"ترجمه رسمی","en":"Official translation"}},{"name":{"fa":"پاسپورت معتبر","en":"Valid passport"},"required":true,"note":{"fa":"حداقل ۱۸ ماه اعتبار","en":"At least 18 months validity"}},{"name":{"fa":"عکس بیومتریک","en":"Biometric photo"},"required":true,"note":{"fa":"۶ قطعه ۳.۵×۴.۵ زمینه سفید","en":"6 copies, 3.5×4.5 cm, white background"}},{"name":{"fa":"مدرک زبان (TOEFL/IELTS یا YDS)","en":"Language certificate (TOEFL/IELTS or YDS)"},"required":false,"note":{"fa":"در نبود مدرک، آزمون تعیین سطح دانشگاه + سال آمادگی زبان","en":"Without it: university placement test + preparatory year"}},{"name":{"fa":"دنکلیک (معادل‌سازی دیپلم)","en":"Denklik (diploma equivalence)"},"required":true,"note":{"fa":"پس از پذیرش، از کنسولگری ترکیه یا اداره آموزش استانی","en":"After acceptance, from the Turkish consulate or provincial education office"}},{"name":{"fa":"فرم درخواست آنلاین و فیش پرداخت","en":"Online application form + fee receipt"},"required":true}]'::jsonb, '[{"name":"YÖS (دانشگاه‌های دولتی / TR-YÖS)","min":"۶۰+/۱۰۰ برای مهندسی، ۸۰+ برای پزشکی","note":{"fa":"آزمون استعداد ریاضی/هندسه؛ ایرانی‌ها معمولاً نتایج عالی می‌گیرند","en":"Math/geometry aptitude test; Iranian students typically score very well"}},{"name":"SAT","min":"1100+ (1300+ medicine)","note":{"fa":"بیشتر دولتی‌ها SAT را هم می‌پذیرند","en":"Most public universities also accept SAT"}},{"name":"دیپلم / کنکور ایران","min":"معدل ۱۷+ برای رشته‌های رقابتی","note":{"fa":"برخی دانشگاه‌ها رتبه کنکور را هم قبول می‌کنند","en":"Some accept the Iranian Konkur rank"}}]'::jsonb, '[{"term":{"fa":"آزمون YÖS و ثبت‌نام بین‌المللی","en":"YÖS exam + international application window"},"date":"2026-07-01"}]'::jsonb, '{"fa":"دانشگاه‌های دولتی ظرفیت محدود بین‌المللی دارند؛ ثبت‌نام زودهنگام و نمره YÖS/SAT بالا کلید پذیرش است. ادیوویز شما را برای آزمون آماده و پرونده را پیگیری می‌کند.","en":"Public universities have limited international quotas; early application and a strong YÖS/SAT score are key. Eduways prepares you for the exam and tracks your file."}'::jsonb) on conflict (id) do update set university_id = excluded.university_id, level = excluded.level, documents = excluded.documents, exams = excluded.exams, deadlines = excluded.deadlines, notes = excluded.notes;
