insert into public.admission_requirements (id, university_id, level, documents, exams, deadlines, notes) values ('req-turkish-german-university-master', 'uni-turkish-german-university', 'master', '[{"name":{"fa":"دانشنامه کارشناسی","en":"Bachelor diploma"},"required":true,"note":{"fa":"ترجمه رسمی و تأیید","en":"Official translation and attestation"}},{"name":{"fa":"ریزنمرات کارشناسی","en":"Bachelor transcript"},"required":true,"note":{"fa":"معدل بالای ۲.۵/۴ یا ۱۴/۲۰ توصیه می‌شود","en":"GPA above 2.5/4 (≈14/20) recommended"}},{"name":{"fa":"پاسپورت معتبر","en":"Valid passport"},"required":true},{"name":{"fa":"انگیزه‌نامه (SOP)","en":"Statement of purpose"},"required":true},{"name":{"fa":"دو توصیه‌نامه","en":"Two reference letters"},"required":true},{"name":{"fa":"رزومه (CV)","en":"CV"},"required":true},{"name":{"fa":"مدرک زبان انگلیسی","en":"English certificate"},"required":false,"note":{"fa":"برای برنامه‌های انگلیسی؛ در نبود آن آزمون دانشگاه","en":"For English programs; otherwise a university exam"}},{"name":{"fa":"نمره GRE/GMAT یا ALES","en":"GRE/GMAT or ALES"},"required":false,"note":{"fa":"برخی دانشگاه‌ها برای رشته‌های مهندسی/MBA","en":"Some universities for engineering/MBA"}},{"name":{"fa":"عکس بیومتریک","en":"Biometric photo"},"required":true}]'::jsonb, array[]::text[], '[{"term":{"fa":"ترم پاییز (شروع سپتامبر)","en":"Fall term (starts September)"},"date":"2026-08-15"},{"term":{"fa":"ترم بهار (شروع فوریه)","en":"Spring term (starts February)"},"date":"2027-01-15"}]'::jsonb, '{"fa":"دانشگاه‌های دولتی ظرفیت محدود بین‌المللی دارند؛ ثبت‌نام زودهنگام و نمره YÖS/SAT بالا کلید پذیرش است. ادیوویز شما را برای آزمون آماده و پرونده را پیگیری می‌کند.","en":"Public universities have limited international quotas; early application and a strong YÖS/SAT score are key. Eduways prepares you for the exam and tracks your file."}'::jsonb) on conflict (id) do update set university_id = excluded.university_id, level = excluded.level, documents = excluded.documents, exams = excluded.exams, deadlines = excluded.deadlines, notes = excluded.notes;
insert into public.admission_requirements (id, university_id, level, documents, exams, deadlines, notes) values ('req-turkish-german-university-phd', 'uni-turkish-german-university', 'phd', '[{"name":{"fa":"دانشنامه و ریزنمرات ارشد و کارشناسی","en":"Master + bachelor diplomas and transcripts"},"required":true},{"name":{"fa":"پروپوزال پژوهشی","en":"Research proposal"},"required":true},{"name":{"fa":"پذیرش اولیه از استاد راهنما","en":"Supervisor pre-acceptance (email)"},"required":false,"note":{"fa":"شانس پذیرش و بورسیه را بسیار بالا می‌برد","en":"Greatly increases admission and funding chances"}},{"name":{"fa":"مدرک زبان انگلیسی (حداقل B2)","en":"English certificate (min. B2)"},"required":true},{"name":{"fa":"ALES/GRE","en":"ALES/GRE"},"required":false},{"name":{"fa":"دو توصیه‌نامه آکادمیک","en":"Two academic references"},"required":true},{"name":{"fa":"پاسپورت و عکس","en":"Passport and photos"},"required":true}]'::jsonb, array[]::text[], '[{"term":{"fa":"ترم پاییز (شروع سپتامبر)","en":"Fall term (starts September)"},"date":"2026-08-15"},{"term":{"fa":"ترم بهار (شروع فوریه)","en":"Spring term (starts February)"},"date":"2027-01-15"}]'::jsonb, '{"fa":"دانشگاه‌های دولتی ظرفیت محدود بین‌المللی دارند؛ ثبت‌نام زودهنگام و نمره YÖS/SAT بالا کلید پذیرش است. ادیوویز شما را برای آزمون آماده و پرونده را پیگیری می‌کند.","en":"Public universities have limited international quotas; early application and a strong YÖS/SAT score are key. Eduways prepares you for the exam and tracks your file."}'::jsonb) on conflict (id) do update set university_id = excluded.university_id, level = excluded.level, documents = excluded.documents, exams = excluded.exams, deadlines = excluded.deadlines, notes = excluded.notes;
