insert into public.admission_requirements (id, university_id, level, documents, exams, deadlines, notes) values ('req-istinye-university-bachelor', 'uni-istinye-university', 'bachelor', '[{"name":{"fa":"دیپلم دبیرستان (یا پیش‌دانشگاهی)","en":"High-school diploma"},"required":true,"note":{"fa":"ترجمه رسمی ترکی یا انگلیسی + تأیید نوتر/کنسولگری","en":"Official Turkish/English translation + notary/consulate attestation"}},{"name":{"fa":"ریزنمرات سه سال آخر دبیرستان","en":"High-school transcript (last 3 years)"},"required":true,"note":{"fa":"ترجمه رسمی","en":"Official translation"}},{"name":{"fa":"پاسپورت معتبر","en":"Valid passport"},"required":true,"note":{"fa":"حداقل ۱۸ ماه اعتبار","en":"At least 18 months validity"}},{"name":{"fa":"عکس بیومتریک","en":"Biometric photo"},"required":true,"note":{"fa":"۶ قطعه ۳.۵×۴.۵ زمینه سفید","en":"6 copies, 3.5×4.5 cm, white background"}},{"name":{"fa":"مدرک زبان (TOEFL/IELTS یا YDS)","en":"Language certificate (TOEFL/IELTS or YDS)"},"required":false,"note":{"fa":"در نبود مدرک، آزمون تعیین سطح دانشگاه + سال آمادگی زبان","en":"Without it: university placement test + preparatory year"}},{"name":{"fa":"دنکلیک (معادل‌سازی دیپلم)","en":"Denklik (diploma equivalence)"},"required":true,"note":{"fa":"پس از پذیرش، از کنسولگری ترکیه یا اداره آموزش استانی","en":"After acceptance, from the Turkish consulate or provincial education office"}},{"name":{"fa":"فرم درخواست آنلاین و فیش پرداخت","en":"Online application form + fee receipt"},"required":true}]'::jsonb, '[{"name":"معدل دیپلم","min":"اغلب بدون حداقل؛ برای پزشکی/دندانپزشکی ۱۷+ و برای بورسیه بالاتر","note":{"fa":"اکثر دانشگاه‌های خصوصی فقط با دیپلم پذیرش می‌دهند","en":"Most private universities admit on diploma alone"}},{"name":"SAT / YÖS (برای بورسیه)","min":"SAT 1200+ → 25–100% بورسیه","note":{"fa":"اختیاری اما برای تخفیف بیشتر مؤثر","en":"Optional but boosts scholarships"}}]'::jsonb, '[{"term":{"fa":"ترم پاییز (شروع سپتامبر)","en":"Fall term (starts September)"},"date":"2026-08-15"},{"term