insert into public.services (id, slug, icon, "order", title, summary, body, steps, price_note) values ('svc-university-admission', 'university-admission', 'GraduationCap', 1, '{"fa":"پذیرش دانشگاه","en":"University admission"}'::jsonb, '{"fa":"انتخاب دانشگاه، آماده‌سازی مدارک و ثبت درخواست تا دریافت نامه پذیرش.","en":"University selection, document prep and application filing until your acceptance letter."}'::jsonb, '{"fa":"ما با معدل، بودجه و هدف شما شروع می‌کنیم، فهرست کوتاهی از دانشگاه‌هایی می‌سازیم که واقعاً پذیرش می‌گیرید، مدارک را ترجمه و تأیید می‌کنیم و درخواست را از طرف شما ثبت و پیگیری می‌کنیم. برای دانشگاه‌های دولتی، برای آزمون YÖS هم آماده‌تان می‌کنیم.","en":"We start from your GPA, budget and goals, build a shortlist of universities where you will actually be accepted, translate and attest your documents, then file and track the application on your behalf. For public universities we also prepare you for the YÖS exam."}'::jsonb, '[{"title":{"fa":"مشاوره و ارزیابی","en":"Consultation & assessment"},"body":{"fa":"جلسه رایگان و ارزیابی شانس پذیرش","en":"Free call and a realistic admission assessment"}},{"title":{"fa":"فهرست کوتاه","en":"Shortlist"},"body":{"fa":"۳–۵ دانشگاه با هزینه و احتمال پذیرش","en":"3–5 universities with cost and acceptance odds"}},{"title":{"fa":"مدارک","en":"Documents"},"body":{"fa":"ترجمه، نوتر و دنکلیک","en":"Translation, notary and denklik"}},{"title":{"fa":"ثبت و پیگیری","en":"File & track"},"body":{"fa":"ثبت درخواست، پیگیری و دریافت پذیرش","en":"Filing, follow-up and acceptance letter"}}]'::jsonb, '{"fa":"مشاوره رایگان · هزینه خدمات پس از پذیرش قطعی","en":"Free consultation · service fee after confirmed acceptance"}'::jsonb) on conflict (id) do update set slug = excluded.slug, icon = excluded.icon, "order" = excluded."order", title = excluded.title, summary = excluded.summary, body = excluded.body, steps = excluded.steps, price_note = excluded.price_note;
insert into public.services (id, slug, icon, "order", title, summary, body, steps, price_note) values ('svc-scholarships-discounts', 'scholarships-discounts', 'BadgePercent', 2, '{"fa":"تخفیف شهریه و بورسیه","en":"Tuition discounts & scholarships"}'::jsonb, '{"fa":"قراردادهای مستقیم با دانشگاه‌ها: تا ۷۵٪ تخفیف روی قیمت رسمی.","en":"Direct agreements with universities: up to 75% off list tuition."}'::jsonb, '{"fa":"بسیاری از دانشگاه‌های خصوصی استانبول قیمت رسمی را روی سایت می‌نویسند اما به نمایندگان رسمی تخفیف می‌دهند. ادیوویز با ده‌ها دانشگاه قرارداد دارد و این تخفیف را مستقیماً به شما منتقل می‌کند. برای بورسیه دولتی ترکیه و بورسیه‌های شایستگی هم پرونده‌تان را آماده می‌کنیم.","en":"Many private universities in Istanbul publish list prices but give discounts to official representatives. Eduways holds agreements with dozens of universities and passes that discount straight to you. We also prepare files for Türkiye Scholarships and merit awards."}'::jsonb, '[{"title":{"fa":"بررسی واجد شرایط بودن","en":"Eligibility check"},"body":{"fa":"معدل، آزمون‌ها و بودجه","en":"GPA, exams, budget"}},{"title":{"fa":"درخواست تخفیف","en":"Negotiation"},"body":{"fa":"درخواست رسمی تخفیف از دانشگاه","en":"Formal discount request to the university"}},{"title":{"fa":"تأیید کتبی","en":"Written confirmation"},"body":{"fa":"تخفیف در نامه پذیرش درج می‌شود","en":"Discount written into your acceptance letter"}}]'::jsonb, '{"fa":"رایگان برای دانشجویان ادیوویز","en":"Free for Eduways students"}'::jsonb) on conflict (id) do update set slug = excluded.slug, icon = excluded.icon, "order" = excluded."order", title = excluded.title, summary = excluded.summary, body = excluded.body, steps = excluded.steps, price_note = excluded.price_note;
insert into public.services (id, slug, icon, "order", title, summary, body, steps, price_note) values ('svc-student-visa', 'student-visa', 'StampIcon', 3, '{"fa":"ویزای تحصیلی","en":"Student visa"}'::jsonb, '{"fa":"آماده‌سازی مدارک ویزا، وقت سفارت و پیگیری تا صدور.","en":"Visa paperwork, consulate appointment and follow-up until issuance."}'::jsonb, '{"fa":"با نامه پذیرش نهایی، پرونده ویزای تحصیلی را آماده می‌کنیم: فرم، بیمه، رزرو اقامت، تمکن مالی، ترجمه‌ها. وقت سفارت می‌گیریم و برای مصاحبه راهنمایی‌تان می‌کنیم.","en":"With the final acceptance letter we prepare the student visa file: form, insurance, accommodation booking, proof of funds, translations. We book the consulate appointment and coach you for the interview."}'::jsonb, '[{"title":{"fa":"چک‌لیست","en":"Checklist"},"body":{"fa":"فهرست دقیق مدارک بر اساس کشور شما","en":"Exact document list for your country"}},{"title":{"fa":"وقت سفارت","en":"Appointment"},"body":{"fa":"رزرو وقت و آماده‌سازی پرونده","en":"Booking and file preparation"}},{"title":{"fa":"پیگیری","en":"Follow-up"},"body":{"fa":"تا صدور ویزا","en":"Until the visa is issued"}}]'::jsonb, null) on conflict (id) do update set slug = excluded.slug, icon = excluded.icon, "order" = excluded."order", title = excluded.title, summary = excluded.summary, body = excluded.body, steps = excluded.steps, price_note = excluded.price_note;
insert into public.services (id, slug, icon, "order", title, summary, body, steps, price_note) values ('svc-flights-airport', 'flights-airport', 'Plane', 4, '{"fa":"بلیت و استقبال فرودگاهی","en":"Flights & airport pickup"}'::jsonb, '{"fa":"بهترین بلیت با بار دانشجویی و استقبال در فرودگاه استانبول.","en":"Best fares with student baggage and pickup at Istanbul airport."}'::jsonb, '{"fa":"بلیت را با بهترین قیمت و بار اضافه رزرو می‌کنیم و یکی از همکاران ما در فرودگاه منتظر شماست تا به محل اقامت برساندتان.","en":"We book the best fare with extra baggage, and a team member meets you at the airport and takes you to your accommodation."}'::jsonb, '[{"title":{"fa":"رزرو","en":"Booking"},"body":{"fa":"بلیت و بار دانشجویی","en":"Ticket + student baggage"}},{"title":{"fa":"استقبال","en":"Pickup"},"body":{"fa":"تابلو به نام شما در فرودگاه","en":"Name board at the airport"}},{"title":{"fa":"انتقال","en":"Transfer"},"body":{"fa":"تا درب خوابگاه/خانه","en":"To your dorm/flat door"}}]'::jsonb, null) on conflict (id) do update set slug = excluded.slug, icon = excluded.icon, "order" = excluded."order", title = excluded.title, summary = excluded.summary, body = excluded.body, steps = excluded.steps, price_note = excluded.price_note;
insert into public.services (id, slug, icon, "order", title, summary, body, steps, price_note) values ('svc-accommodation', 'accommodation', 'Home', 5, '{"fa":"خوابگاه و اسکان","en":"Accommodation"}'::jsonb, '{"fa":"خوابگاه دانشگاه، خوابگاه خصوصی یا آپارتمان اشتراکی نزدیک پردیس.","en":"University dorm, private residence or shared flat near campus."}'::jsonb, '{"fa":"بر اساس بودجه و پردیس، گزینه‌های امن و نزدیک را معرفی و رزرو می‌کنیم. قرارداد اجاره را بررسی می‌کنیم تا گرفتار مشکلات رایج نشوید.","en":"Based on budget and campus we source and book safe, nearby options and review the lease so you avoid common pitfalls."}'::jsonb, '[{"title":{"fa":"نیازسنجی","en":"Needs"},"body":{"fa":"بودجه، پردیس، هم‌اتاقی","en":"Budget, campus, roommates"}},{"title":{"fa":"گزینه‌ها","en":"Options"},"body":{"fa":"۳ گزینه با عکس و قیمت","en":"3 options with photos and prices"}},{"title":{"fa":"رزرو","en":"Booking"},"body":{"fa":"قرارداد و تحویل کلید","en":"Lease and key handover"}}]'::jsonb, null) on conflict (id) do update set slug = excluded.slug, icon = excluded.icon, "order" = excluded."order", title = excluded.title, summary = excluded.summary, body = excluded.body, steps = excluded.steps, price_note = excluded.price_note;
insert into public.services (id, slug, icon, "order", title, summary, body, steps, price_note) values ('svc-residence-permit', 'residence-permit', 'IdCard', 6, '{"fa":"اقامت دانشجویی (کیملیک)","en":"Residence permit (ikamet)"}'::jsonb, '{"fa":"ثبت درخواست اقامت، بیمه، آدرس و وقت اداره مهاجرت.","en":"Residence application, insurance, address registration and immigration appointment."}'::jsonb, '{"fa":"ظرف ۳۰ روز بعد از ورود باید درخواست اقامت بدهید. ما فرم e-ikamet را پر می‌کنیم، بیمه را می‌گیریم، وقت اداره مهاجرت را رزرو می‌کنیم و همراهتان می‌آییم.","en":"You must apply within 30 days of arrival. We complete the e-ikamet form, arrange insurance, book the immigration appointment and come with you."}'::jsonb, '[{"title":{"fa":"مدارک","en":"Documents"},"body":{"fa":"بیمه، آدرس، عکس، پاسپورت","en":"Insurance, address, photos, passport"}},{"title":{"fa":"وقت","en":"Appointment"},"body":{"fa":"رزرو و همراهی","en":"Booking and accompaniment"}},{"title":{"fa":"کارت","en":"Card"},"body":{"fa":"پیگیری تا تحویل کارت","en":"Tracking until the card arrives"}}]'::jsonb, null) on conflict (id) do update set slug = excluded.slug, icon = excluded.icon, "order" = excluded."order", title = excluded.title, summary = excluded.summary, body = excluded.body, steps = excluded.steps, price_note = excluded.price_note;
insert into public.services (id, slug, icon, "order", title, summary, body, steps, price_note) values ('svc-settling-in', 'settling-in', 'MapPinned', 7, '{"fa":"استقرار در استانبول","en":"Settling in Istanbul"}'::jsonb, '{"fa":"سیم‌کارت، حساب بانکی، کارت حمل‌ونقل، ثبت‌نام دانشگاه و راهنمای شهر.","en":"SIM card, bank account, transport card, university registration and a city orientation."}'::jsonb, '{"fa":"در هفته اول با شما هستیم: ثبت‌نام نهایی دانشگاه، کارت دانشجویی، سیم‌کارت، حساب بانکی، کارت استانبول و معرفی محله.","en":"We stay with you through the first week: final registration, student card, SIM, bank account, Istanbulkart and a neighbourhood walk-through."}'::jsonb, '[{"title":{"fa":"روز اول","en":"Day one"},"body":{"fa":"ثبت‌نام و کارت دانشجویی","en":"Registration and student card"}},{"title":{"fa":"هفته اول","en":"First week"},"body":{"fa":"سیم‌کارت، بانک، حمل‌ونقل","en":"SIM, bank, transport"}},{"title":{"fa":"همیشه","en":"Always"},"body":{"fa":"پشتیبانی واتساپ","en":"WhatsApp support"}}]'::jsonb, null) on conflict (id) do update set slug = excluded.slug, icon = excluded.icon, "order" = excluded."order", title = excluded.title, summary = excluded.summary, body = excluded.body, steps = excluded.steps, price_note = excluded.price_note;
insert into public.services (id, slug, icon, "order", title, summary, body, steps, price_note) values ('svc-language-prep', 'language-prep', 'Languages', 8, '{"fa":"آمادگی زبان و YÖS","en":"Language & YÖS preparation"}'::jsonb, '{"fa":"کلاس‌های TÖMER/ترکی، انگلیسی و آمادگی آزمون YÖS با مدرسان فارسی‌زبان.","en":"TÖMER/Turkish, English and YÖS prep with Persian-speaking instructors."}'::jsonb, '{"fa":"برای دانشگاه‌های دولتی آزمون YÖS و برای برنامه‌های ترکی مدرک TÖMER لازم است. دوره‌های فشرده آنلاین و حضوری برگزار می‌کنیم.","en":"Public universities need YÖS and Turkish programs need TÖMER. We run intensive online and in-person courses."}'::jsonb, '[{"title":{"fa":"تعیین سطح","en":"Placement"},"body":{"fa":"آزمون سطح رایگان","en":"Free placement test"}},{"title":{"fa":"دوره","en":"Course"},"body":{"fa":"آنلاین یا حضوری در استانبول","en":"Online or in Istanbul"}},{"title":{"fa":"آزمون","en":"Exam"},"body":{"fa":"ثبت‌نام و همراهی در روز آزمون","en":"Registration and exam-day support"}}]'::jsonb, null) on conflict (id) do update set slug = excluded.slug, icon = excluded.icon, "order" = excluded."order", title = excluded.title, summary = excluded.summary, body = excluded.body, steps = excluded.steps, price_note = excluded.price_note;
insert into public.stories (id, slug, student_name, university_id, program, country, year_enrolled, published_at, photo_url, quote, body) values ('story-1', 'sara-medipol-dentistry', 'سارا م.', 'uni-medipol-university', '{"fa":"دندانپزشکی (انگلیسی)","en":"Dentistry (English)"}'::jsonb, 'IR', 2024, '2024-10-02', null, '{"fa":"فکر می‌کردم دندانپزشکی با این بودجه غیرممکنه. ادیوویز ۳۰٪ تخفیف گرفت و خوابگاه رو هم قبل از رسیدنم رزرو کرد.","en":"I thought dentistry was impossible on my budget. Eduways got 30% off and had my dorm booked before I landed."}'::jsonb, '{"fa":"سارا با معدل ۱۸.۲ از شیراز به ما پیام داد. در ۱۰ روز پذیرش مشروط مدیپول را گرفتیم، تخفیف را کتبی کردیم و پرونده ویزا آماده شد. سپتامبر ۲۰۲۴ ترم اول را شروع کرد.","en":"Sara messaged us from Shiraz with an 18.2 GPA. Within 10 days we had her conditional acceptance at Medipol, the discount in writing and her visa file ready. She started in September 2024."}'::jsonb) on conflict (id) do update set slug = excluded.slug, student_name = excluded.student_name, university_id = excluded.university_id, program = excluded.program, country = excluded.country, year_enrolled = excluded.year_enrolled, published_at = excluded.published_at, photo_url = excluded.photo_url, quote = excluded.quote, body = excluded.body;
insert into public.stories (id, slug, student_name, university_id, program, country, year_enrolled, published_at, photo_url, quote, body) values ('story-2', 'amirhossein-itu-computer', 'امیرحسین ک.', 'uni-istanbul-technical-university', '{"fa":"مهندسی کامپیوتر","en":"Computer Engineering"}'::jsonb, 'IR', 2023, '2023-11-15', null, '{"fa":"برای YÖS سه ماه با مدرس ادیوویز کار کردم و ۸۶ گرفتم. الان ITÜ با شهریه سالی ۴ هزار دلار.","en":"I studied three months for YÖS with an Eduways tutor and scored 86. Now ITU at $4k a year."}'::jsonb, '{"fa":"امیرحسین هدفش فقط دانشگاه دولتی بود. با برنامه آمادگی YÖS و ثبت‌نام در سه دانشگاه دولتی، ITÜ پذیرفته شد.","en":"Amirhossein only wanted a public university. With our YÖS program and applications to three public schools, ITU accepted him."}'::jsonb) on conflict (id) do update set slug = excluded.slug, student_name = excluded.student_name, university_id = excluded.university_id, program = excluded.program, country = excluded.country, year_enrolled = excluded.year_enrolled, published_at = excluded.published_at, photo_url = excluded.photo_url, quote = excluded.quote, body = excluded.body;
