insert into public.stories (id, slug, student_name, university_id, program, country, year_enrolled, published_at, photo_url, quote, body) values ('story-5', 'niloofar-aydin-nursing', 'نیلوفر ه.', 'uni-istanbul-aydin-university', '{"fa":"پرستاری (انگلیسی)","en":"Nursing (English)"}'::jsonb, 'IR', 2025, '2025-10-05', null, '{"fa":"شهریه با تخفیف ادیوویز شد ۲۵۰۰ دلار. پدرم باورش نمی‌شد.","en":"With the Eduways discount tuition came to $2,500. My father could not believe it."}'::jsonb, '{"fa":"نیلوفر با بودجه محدود می‌خواست پرستاری انگلیسی بخواند. آیدین با ۵۰٪ تخفیف بهترین گزینه بود.","en":"Niloofar wanted English-taught nursing on a tight budget. Aydın with 50% off was the best fit."}'::jsonb) on conflict (id) do update set slug = excluded.slug, student_name = excluded.student_name, university_id = excluded.university_id, program = excluded.program, country = excluded.country, year_enrolled = excluded.year_enrolled, published_at = excluded.published_at, photo_url = excluded.photo_url, quote = excluded.quote, body = excluded.body;
insert into public.stories (id, slug, student_name, university_id, program, country, year_enrolled, published_at, photo_url, quote, body) values ('story-6', 'farhad-sabanci-engineering', 'فرهاد ن.', 'uni-sabanci-university', '{"fa":"مهندسی (انتخاب رشته سال دوم)","en":"Engineering (major declared in year 2)"}'::jsonb, 'TJ', 2024, '2024-11-11', null, '{"fa":"SAT 1420 داشتم و سابانجی ۱۰۰٪ بورسیه داد. ادیوویز فقط کمک کرد درست اقدام کنم.","en":"I had SAT 1420 and Sabancı gave 100%. Eduways made sure I applied right."}'::jsonb, '{"fa":"پرونده فرهاد دو هفته قبل از ددلاین کامل شد و بورسیه کامل گرفت.","en":"Farhad’s file was complete two weeks before the deadline and he got a full scholarship."}'::jsonb) on conflict (id) do update set slug = excluded.slug, student_name = excluded.student_name, university_id = excluded.university_id, program = excluded.program, country = excluded.country, year_enrolled = excluded.year_enrolled, published_at = excluded.published_at, photo_url = excluded.photo_url, quote = excluded.quote, body = excluded.body;
insert into public.posts (id, slug, tags, author, published_at, reading_minutes, cover_url, title, excerpt, body) values ('post-1', 'study-in-turkey-cost-2026', array['costs','istanbul']::text[], 'Eduways', '2026-07-10', 7, null, '{"fa":"هزینه تحصیل و زندگی در استانبول ۲۰۲۶ (به دلار)","en":"Cost of studying and living in Istanbul in 2026 (in USD)"}'::jsonb, '{"fa":"شهریه دولتی از ۱۰۰۰ دلار، خصوصی از ۳۰۰۰ دلار؛ اجاره، خوراک و حمل‌ونقل ماهانه چقدر می‌شود؟","en":"Public tuition from $1,000, private from $3,000; what do rent, food and transport cost per month?"}'::jsonb, '{"fa":"## شهریه\n\nدانشگاه‌های دولتی استانبول برای دانشجوی بین‌المللی بین **۱۰۰۰ تا ۹۰۰۰ دلار** در سال می‌گیرند (پزشکی گران‌ترین). دانشگاه‌های خصوصی از **۲۵۰۰ دلار** (مهندسی در دانشگاه‌های ارزان) تا **۳۵ هزار دلار** (پزشکی کوچ) متغیر است — اما با تخفیف نمایندگی معمولاً ۳۰ تا ۵۰٪ کمتر می‌پردازید.\n\n## اجاره\n\n- اتاق در خانه اشتراکی: ۲۰۰–۴۵۰ دلار\n- خوابگاه خصوصی: ۲۵۰–۵۰۰ دلار\n- سوئیت شخصی: ۵۰۰–۹۰۰ دلار\n\n## زندگی\n\nخوراک و حمل‌ونقل دانشجویی حدود ۲۵۰–۴۰۰ دلار در ماه. کارت حمل‌ونقل دانشجویی بسیار ارزان است.\n\n## جمع‌بندی\n\nیک دانشجوی مهندسی در دانشگاه خصوصی متوسط با تخفیف: حدود **۸ تا ۱۲ هزار دلار** در سال با همه هزینه‌ها. از [محاسبه‌گر هزینه](/calculator) استفاده کنید.","en":"## Tuition\n\nIstanbul’s public universities charge international students **$1,000–9,000** per year (medicine at the top). Private universities range from **$2,500** (engineering at budget schools) to **$35,000** (Koç medicine) — but with representative discounts you usually pay 30–50% less.\n\n## Rent\n\n- Room in a shared flat: $200–450\n- Private dorm: $250–500\n- Studio: $500–900\n\n## Living\n\nStudent food and transport run about $250–400 a month. The student transport card is very cheap.\n\n## Bottom line\n\nAn engineering student at a mid-range private university with a discount: roughly **$8–12k** per year all-in. Try the [cost calculator](/calculator)."}'::jsonb) on conflict (id) do update set slug = excluded.slug, tags = excluded.tags, author = excluded.author, published_at = excluded.published_at, reading_minutes = excluded.reading_minutes, cover_url = excluded.cover_url, title = excluded.title, excerpt = excluded.excerpt, body = excluded.body;
insert into public.posts (id, slug, tags, author, published_at, reading_minutes, cover_url, title, excerpt, body) values ('post-2', 'yos-exam-guide', array['admission','yos']::text[], 'Eduways', '2026-06-02', 9, null, '{"fa":"راهنمای کامل آزمون YÖS برای ایرانی‌ها","en":"The complete YÖS guide for Iranian students"}'::jsonb, '{"fa":"YÖS چیست، کدام دانشگاه‌ها می‌خواهند، چه نمره‌ای کافی است و چطور آماده شویم.","en":"What YÖS is, which universities require it, what score is enough and how to prepare."}'::jsonb, '{"fa":"## YÖS چیست؟\n\nآزمون ورودی دانشجویان خارجی برای دانشگاه‌های دولتی ترکیه؛ ۸۰ سؤال ریاضی، هندسه و هوش در ۱۰۰ دقیقه. از ۲۰۲۳ آزمون سراسری **TR-YÖS** توسط ÖSYM برگزار می‌شود و اکثر دولتی‌ها آن را می‌پذیرند؛ برخی (مثل دانشگاه استانبول) آزمون خودشان را هم دارند.\n\n## چه نمره‌ای لازم است؟\n\n- مهندسی ITÜ/YTÜ: ۷۰–۸۵\n- پزشکی دانشگاه استانبول: ۹۰+\n- رشته‌های علوم انسانی: ۵۰–۶۵\n\n## آمادگی\n\nدانش‌آموزان ایرانی به‌خاطر ریاضی قوی معمولاً در ۳–۴ ماه آماده می‌شوند. ادیوویز کلاس آنلاین با مدرس فارسی‌زبان دارد.\n\n## جایگزین‌ها\n\nSAT (1100+) را اغلب دولتی‌ها می‌پذیرند. دانشگاه‌های خصوصی اصلاً YÖS نمی‌خواهند.","en":"## What is YÖS?\n\nThe foreign student entrance exam for Turkish public universities; 80 math, geometry and IQ questions in 100 minutes. Since 2023 the centralised **TR-YÖS** by ÖSYM is accepted by most public universities; some (like Istanbul University) also run their own.\n\n## What score do you need?\n\n- ITU/YTU engineering: 70–85\n- Istanbul University medicine: 90+\n- Humanities: 50–65\n\n## Preparation\n\nIranian students with strong math usually prepare in 3–4 months. Eduways runs online classes with Persian-speaking tutors.\n\n## Alternatives\n\nSAT (1100+) is accepted by most public universities. Private universities do not require YÖS at all."}'::jsonb) on conflict (id) do update set slug = excluded.slug, tags = excluded.tags, author = excluded.author, published_at = excluded.published_at, reading_minutes = excluded.reading_minutes, cover_url = excluded.cover_url, title = excluded.title, excerpt = excluded.excerpt, body = excluded.body;
insert into public.posts (id, slug, tags, author, published_at, reading_minutes, cover_url, title, excerpt, body) values ('post-3', 'turkey-student-visa-guide', array['visa']::text[], 'Eduways', '2026-05-14', 6, null, '{"fa":"ویزای تحصیلی ترکیه: مدارک، زمان و نکات مصاحبه","en":"Türkiye student visa: documents, timeline and interview tips"}'::jsonb, '{"fa":"از نامه پذیرش تا مهر ویزا؛ چه مدارکی لازم است و چقدر طول می‌کشد؟","en":"From acceptance letter to visa stamp; what you need and how long it takes."}'::jsonb, '{"fa":"## مدارک\n\nنامه پذیرش نهایی، پاسپورت، فرم ویزا، عکس، بیمه مسافرتی، رزرو اقامت، تمکن مالی (حدود ۵۰۰ دلار برای هر ماه)، ریزنمرات و دیپلم ترجمه‌شده.\n\n## زمان\n\nوقت سفارت در تهران معمولاً ۲–۴ هفته؛ صدور ویزا ۲–۳ هفته. پس حداقل **۲ ماه قبل از شروع ترم** اقدام کنید.\n\n## مصاحبه\n\nکوتاه است: چرا ترکیه، چرا این دانشگاه، هزینه‌ها را چه کسی می‌پردازد. صادق و مرتب باشید.\n\n## بعد از ورود\n\nظرف ۳۰ روز درخواست اقامت دانشجویی بدهید — ما همراهتان هستیم.","en":"## Documents\n\nFinal acceptance letter, passport, visa form, photos, travel insurance, accommodation booking, proof of funds (about $500 per month), translated transcripts and diploma.\n\n## Timeline\n\nConsulate appointments in Tehran take 2–4 weeks; issuance 2–3 weeks. Apply at least **2 months before term starts**.\n\n## Interview\n\nShort: why Türkiye, why this university, who pays. Be honest and organised.\n\n## After arrival\n\nApply for the student residence permit within 30 days — we go with you."}'::jsonb) on conflict (id) do update set slug = excluded.slug, tags = excluded.tags, author = excluded.author, published_at = excluded.published_at, reading_minutes = excluded.reading_minutes, cover_url = excluded.cover_url, title = excluded.title, excerpt = excluded.excerpt, body = excluded.body;
insert into public.posts (id, slug, tags, author, published_at, reading_minutes, cover_url, title, excerpt, body) values ('post-4', 'ikamet-residence-permit-students', array['visa','life']::text[], 'Eduways', '2026-04-21', 5, null, '{"fa":"اقامت دانشجویی (کیملیک) قدم به قدم","en":"Student residence permit (ikamet) step by step"}'::jsonb, '{"fa":"فرم e-ikamet، بیمه، آدرس، وقت اداره مهاجرت و زمان تحویل کارت.","en":"The e-ikamet form, insurance, address, immigration appointment and card delivery."}'::jsonb, '{"fa":"1. ثبت‌نام دانشگاه را نهایی کنید و **نامه دانشجویی (öğrenci belgesi)** بگیرید.\n2. بیمه سلامت خصوصی یا SGK دانشجویی.\n3. قرارداد اجاره یا نامه خوابگاه برای آدرس.\n4. فرم آنلاین e-ikamet و پرداخت هزینه کارت.\n5. وقت اداره مهاجرت (Göç İdaresi) — مدارک را فیزیکی ببرید.\n6. کارت ظرف ۴–۱۰ هفته با پست می‌رسد.\n\nادیوویز همه این مراحل را برای دانشجویانش انجام می‌دهد.","en":"1. Finalise registration and obtain the **student certificate (öğrenci belgesi)**.\n2. Private health insurance or student SGK.\n3. Lease or dorm letter for the address.\n4. Online e-ikamet form and card fee payment.\n5. Immigration office (Göç İdaresi) appointment — bring physical documents.\n6. The card arrives by post in 4–10 weeks.\n\nEduways handles every step for its students."}'::jsonb) on conflict (id) do update set slug = excluded.slug, tags = excluded.tags, author = excluded.author, published_at = excluded.published_at, reading_minutes = excluded.reading_minutes, cover_url = excluded.cover_url, title = excluded.title, excerpt = excluded.excerpt, body = excluded.body;
insert into public.posts (id, slug, tags, author, published_at, reading_minutes, cover_url, title, excerpt, body) values ('post-5', 'best-districts-students-istanbul', array['life','istanbul']::text[], 'Eduways', '2026-03-30', 8, null, '{"fa":"بهترین مناطق استانبول برای زندگی دانشجویی","en":"Best Istanbul neighbourhoods for student life"}'::jsonb, '{"fa":"بشیکتاش، کادیکوی، شیشلی یا آوجیلار؟ مقایسه اجاره، امنیت و دسترسی.","en":"Beşiktaş, Kadıköy, Şişli or Avcılar? Rent, safety and access compared."}'::jsonb, '{"fa":"## اگر بودجه دارید: بشیکتاش و کادیکوی\n\nجوان، امن، پر از کافه و کتابخانه. اجاره اتاق ۴۰۰–۵۰۰ دلار.\n\n## تعادل: شیشلی و اسکودار\n\nمرکزی و با جامعه ایرانی بزرگ. ۳۰۰–۴۵۰ دلار.\n\n## اقتصادی: آوجیلار، اسنلر، زیتین‌بورنو\n\nنزدیک پردیس‌های دولتی و خصوصی غرب شهر. ۲۰۰–۳۰۰ دلار.\n\n## زندگی پردیسی: توزلا و چکمه‌کوی\n\nسابانجی، اوکان، اوزیگین — خوابگاه داخل دانشگاه.\n\nصفحه [مناطق استانبول](/districts) را ببینید.","en":"## If you have the budget: Beşiktaş and Kadıköy\n\nYoung, safe, full of cafés and libraries. Rooms $400–500.\n\n## Balanced: Şişli and Üsküdar\n\nCentral with a large Iranian community. $300–450.\n\n## Economical: Avcılar, Esenler, Zeytinburnu\n\nNear the western public and private campuses. $200–300.\n\n## Campus life: Tuzla and Çekmeköy\n\nSabancı, Okan, Özyeğin — on-campus dorms.\n\nSee the [Istanbul districts](/districts) page."}'::jsonb) on conflict (id) do update set slug = excluded.slug, tags = excluded.tags, author = excluded.author, published_at = excluded.published_at, reading_minutes = excluded.reading_minutes, cover_url = excluded.cover_url, title = excluded.title, excerpt = excluded.excerpt, body = excluded.body;
insert into public.posts (id, slug, tags, author, published_at, reading_minutes, cover_url, title, excerpt, body) values ('post-6', 'sat-scholarships-turkey', array['admission','scholarships']::text[], 'Eduways', '2026-02-18', 6, null, '{"fa":"با SAT چقدر بورسیه می‌گیرید؟ جدول دانشگاه به دانشگاه","en":"How much scholarship does SAT get you? University by university"}'::jsonb, '{"fa":"کوچ، سابانجی، اوزیگین، BAU و بیلگی: نمره SAT و درصد بورسیه.","en":"Koç, Sabancı, Özyeğin, BAU and Bilgi: SAT score versus scholarship percentage."}'::jsonb, '{"fa":"| دانشگاه | SAT | بورسیه |\n|---|---|---|\n| کوچ | 1450+ | ۱۰۰٪ |\n| کوچ | 1300–1449 | ۵۰٪ |\n| سابانجی | 1400+ | ۱۰۰٪ |\n| اوزیگین | 1400+ | ۱۰۰٪ |\n| BAU | 1300+ | ۷۵٪ |\n| بیلگی | 1200+ | ۵۰–۷۵٪ |\n\nSAT در تهران برگزار نمی‌شود؛ دانش‌آموزان ایرانی معمولاً در استانبول، دبی یا ایروان امتحان می‌دهند. ادیوویز ثبت‌نام و اقامت روز آزمون را هماهنگ می‌کند.","en":"| University | SAT | Scholarship |\n|---|---|---|\n| Koç | 1450+ | 100% |\n| Koç | 1300–1449 | 50% |\n| Sabancı | 1400+ | 100% |\n| Özyeğin | 1400+ | 100% |\n| BAU | 1300+ | 75% |\n| Bilgi | 1200+ | 50–75% |\n\nSAT is not held in Tehran; Iranian students usually sit it in Istanbul, Dubai or Yerevan. Eduways arranges registration and exam-day stays."}'::jsonb) on conflict (id) do update set slug = excluded.slug, tags = excluded.tags, author = excluded.author, published_at = excluded.published_at, reading_minutes = excluded.reading_minutes, cover_url = excluded.cover_url, title = excluded.title, excerpt = excluded.excerpt, body = excluded.body;
insert into public.faqs (id, category, "order", question, answer) values ('faq-1', 'general', 1, '{"fa":"ادیوویز چه کاری برای من انجام می‌دهد؟","en":"What exactly does Eduways do for me?"}'::jsonb, '{"fa":"از انتخاب دانشگاه و ثبت درخواست تا تخفیف شهریه، ویزا، بلیت، خوابگاه، اقامت و استقرار در استانبول — همه‌چیز را یک تیم انجام می‌دهد.","en":"From choosing the university and filing the application to tuition discounts, visa, flight, housing, residence permit and settling in Istanbul — one team does it all."}'::jsonb) on conflict (id) do update set category = excluded.category, "order" = excluded."order", question = excluded.question, answer = excluded.answer;
insert into public.faqs (id, category, "order", question, answer) values ('faq-2', 'general', 2, '{"fa":"هزینه خدمات ادیوویز چقدر است؟","en":"How much do Eduways services cost?"}'::jsonb, '{"fa":"مشاوره رایگان است. هزینه خدمات بسته به بسته انتخابی متفاوت است و پیش از شروع در قرارداد کتبی مشخص می‌شود. در بسیاری از دانشگاه‌های خصوصی، تخفیفی که می‌گیریم چند برابر هزینه خدمات است.","en":"Consultation is free. Service fees depend on the package and are fixed in a written agreement before we start. At many private universities the discount we secure is several times the fee."}'::jsonb) on conflict (id) do update set category = excluded.category, "order" = excluded."order", question = excluded.question, answer = excluded.answer;
insert into public.faqs (id, category, "order", question, answer) values ('faq-3', 'admission', 3, '{"fa":"بدون YÖS و SAT می‌توانم پذیرش بگیرم؟","en":"Can I get admitted without YÖS or SAT?"}'::jsonb, '{"fa":"بله؛ اکثر دانشگاه‌های خصوصی فقط با دیپلم پذیرش می‌دهند. برای دانشگاه‌های دولتی YÖS یا SAT لازم است.","en":"Yes; most private universities admit on the diploma alone. Public universities require YÖS or SAT."}'::jsonb) on conflict (id) do update set category = excluded.category, "order" = excluded."order", question = excluded.question, answer = excluded.answer;
insert into public.faqs (id, category, "order", question, answer) values ('faq-4', 'admission', 4, '{"fa":"با معدل پایین هم شانس دارم؟","en":"Do I have a chance with a low GPA?"}'::jsonb, '{"fa":"برای مهندسی، مدیریت و علوم انسانی در دانشگاه‌های خصوصی معمولاً بله. پزشکی و دندانپزشکی به معدل بالاتر (۱۷+) نیاز دارند.","en":"For engineering, business and humanities at private universities, usually yes. Medicine and dentistry need a higher GPA (17+/20)."}'::jsonb) on conflict (id) do update set category = excluded.category, "order" = excluded."order", question = excluded.question, answer = excluded.answer;
insert into public.faqs (id, category, "order", question, answer) values ('faq-5', 'admission', 5, '{"fa":"پذیرش چقدر طول می‌کشد؟","en":"How long does admission take?"}'::jsonb, '{"fa":"دانشگاه‌های خصوصی: ۱–۲ هفته برای پذیرش مشروط. دولتی: بستگی به تقویم آزمون و اعلام نتایج دارد (معمولاً تابستان).","en":"Private: 1–2 weeks for conditional acceptance. Public: depends on the exam and results calendar (usually summer)."}'::jsonb) on conflict (id) do update set category = excluded.category, "order" = excluded."order", question = excluded.question, answer = excluded.answer;
insert into public.faqs (id, category, "order", question, answer) values ('faq-6', 'costs', 6, '{"fa":"شهریه را باید یک‌جا پرداخت کنم؟","en":"Do I have to pay tuition all at once?"}'::jsonb, '{"fa":"بیشتر دانشگاه‌ها پرداخت اقساطی (۲ تا ۸ قسط) دارند. پیش‌شهریه برای صدور نامه پذیرش نهایی لازم است.","en":"Most universities offer instalments (2–8). A deposit is needed for the final acceptance letter."}'::jsonb) on conflict (id) do update set category = excluded.category, "order" = excluded."order", question = excluded.question, answer = excluded.answer;
insert into public.faqs (id, category, "order", question, answer) values ('faq-7', 'costs', 7, '{"fa":"تخفیف ادیوویز با بورسیه دانشگاه جمع می‌شود؟","en":"Does the Eduways discount stack with university scholarships?"}'::jsonb, '{"fa":"در بسیاری از دانشگاه‌ها بله تا سقف مشخص. مورد به مورد بررسی و کتبی تأیید می‌کنیم.","en":"At many universities yes, up to a cap. We check case by case and confirm in writing."}'::jsonb) on conflict (id) do update set category = excluded.category, "order" = excluded."order", question = excluded.question, answer = excluded.answer;
insert into public.faqs (id, category, "order", question, answer) values ('faq-8', 'costs', 8, '{"fa":"آیا می‌توانم در حین تحصیل کار کنم؟","en":"Can I work while studying?"}'::jsonb, '{"fa":"دانشجویان کارشناسی بعد از سال اول با اجازه کار می‌توانند پاره‌وقت کار کنند؛ ارشد و دکتری از ابتدا. بازار کار برای فارسی‌زبان‌ها در استانبول فعال است.","en":"Bachelor students can work part-time with a permit after the first year; master/PhD from the start. The job market for Persian speakers in Istanbul is active."}'::jsonb) on conflict (id) do update set category = excluded.category, "order" = excluded."order", question = excluded.question, answer = excluded.answer;
insert into public.faqs (id, category, "order", question, answer) values ('faq-9', 'visa', 9, '{"fa":"ایرانی‌ها برای تحصیل ویزا لازم دارند؟","en":"Do Iranians need a visa to study?"}'::jsonb, '{"fa":"برای ورود توریستی تا ۹۰ روز خیر، اما برای اقامت دانشجویی توصیه می‌کنیم با ویزای تحصیلی وارد شوید تا فرایند کیملیک ساده‌تر باشد. ما هر دو مسیر را راهنمایی می‌کنیم.","en":"Not for tourist entry up to 90 days, but for student residence we recommend entering on a student visa so the ikamet process is smoother. We guide both routes."}'::jsonb) on conflict (id) do update set category = excluded.category, "order" = excluded."order", question = excluded.question, answer = excluded.answer;
insert into public.faqs (id, category, "order", question, answer) values ('faq-10', 'visa', 10, '{"fa":"اقامت دانشجویی چقدر اعتبار دارد؟","en":"How long is the student residence permit valid?"}'::jsonb, '{"fa":"معمولاً یک سال و هر سال تمدید می‌شود تا پایان تحصیل.","en":"Usually one year, renewed annually until graduation."}'::jsonb) on conflict (id) do update set category = excluded.category, "order" = excluded."order", question = excluded.question, answer = excluded.answer;
insert into public.faqs (id, category, "order", question, answer) values ('faq-11', 'life', 11, '{"fa":"استانبول برای دانشجوی دختر امن است؟","en":"Is Istanbul safe for female students?"}'::jsonb, '{"fa":"بله؛ مناطق دانشجویی مثل بشیکتاش، کادیکوی و شیشلی امن و پرجمعیت هستند. خوابگاه‌های دخترانه با نگهبانی ۲۴ ساعته هم فراوان‌اند.","en":"Yes; student districts like Beşiktaş, Kadıköy and Şişli are safe and busy. Women-only residences with 24h security are plentiful."}'::jsonb) on conflict (id) do update set category = excluded.category, "order" = excluded."order", question = excluded.question, answer = excluded.answer;
insert into public.faqs (id, category, "order", question, answer) values ('faq-12', 'life', 12, '{"fa":"زبان ترکی نمی‌دانم؛ مشکلی است؟","en":"I do not speak Turkish; is that a problem?"}'::jsonb, '{"fa":"برای برنامه‌های انگلیسی خیر. برای زندگی روزمره، ۳ ماه کلاس TÖMER کافی است و دانشگاه‌ها دوره رایگان دارند.","en":"Not for English programs. For daily life, 3 months of TÖMER is enough, and universities offer free courses."}'::jsonb) on conflict (id) do update set category = excluded.category, "order" = excluded."order", question = excluded.question, answer = excluded.answer;
